import{_ as s,o as n,c as t,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const d=JSON.parse('{"title":"四年学习规划","description":"","frontmatter":{},"headers":[],"relativePath":"学习规划.md","filePath":"学习规划.md","lastUpdated":1792430298000}'),r={name:"学习规划.md"};function o(i,a,e,p,g,h){return n(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="四年学习规划" tabindex="-1">四年学习规划 <a class="header-anchor" href="#四年学习规划" aria-label="Permalink to &quot;四年学习规划&quot;">​</a></h1><blockquote><p>这是一份<strong>参考性</strong>的四年路线图，基于培养方案课程顺序与网安知识体系的内在依赖整理。请结合自己的节奏调整，重点是理解「为什么要按这个顺序学」。</p></blockquote><h2 id="大一-地基期-编程-工具-数学" tabindex="-1">大一：地基期（编程 + 工具 + 数学） <a class="header-anchor" href="#大一-地基期-编程-工具-数学" aria-label="Permalink to &quot;大一：地基期（编程 + 工具 + 数学）&quot;">​</a></h2><p><strong>目标</strong>：成为「会用工具写程序」的人。</p><ul><li><strong>编程</strong>：以 C 语言入门（对应 FAFU「高级程序设计」），课余补充 Python；</li><li><strong>工具</strong>：Linux 与命令行、Git/GitHub、Vim——详见 <a href="./必学工具/Linux.html">必学工具</a>；</li><li><strong>数学</strong>：高等数学、线性代数认真学，它们是后续「信息安全数学基础」的地基；</li><li><strong>认知</strong>：读完 <a href="./安全方向/网络空间安全导论.html">网络空间安全导论</a>（校内第 2 学期开设），了解这个专业到底做什么；</li><li><strong>兴趣</strong>：逛一圈 <a href="./必学工具/CTF平台与资源.html">CTF 平台与资源</a>，看两道入门题的题解，知道「攻防长什么样」。</li></ul><details class="details custom-block"><summary>大一常见误区</summary><ul><li>只刷题不读文档、不用 Linux；</li><li>把 C 语言当成「考完就扔」的课——它是后续汇编、逆向、操作系统安全的地基。</li></ul></details><h2 id="大二-筑基期-专业基础-安全入门" tabindex="-1">大二：筑基期（专业基础 + 安全入门） <a class="header-anchor" href="#大二-筑基期-专业基础-安全入门" aria-label="Permalink to &quot;大二：筑基期（专业基础 + 安全入门）&quot;">​</a></h2><p><strong>目标</strong>：建立计算机系统全景认知，摸到安全的门。</p><ul><li><strong>专业基础</strong>：数据结构与算法（第 2 学期）、汇编语言（第 4 学期）、计算机网络、操作系统及安全——这四门是网安的核心地基；</li><li><strong>数学转安全</strong>：信息安全数学基础（第 3 学期）→ 现代密码学（第 3 学期）；</li><li><strong>安全起步</strong>：网络安全原理（第 4 学期）、安全协议分析（第 4 学期）、数据库原理及安全（第 4 学期）；</li><li><strong>动手</strong>：开始系统刷 CTF 入门题（Web + Crypto + Misc 起步），把 <a href="./实验与实践/安全实验平台.html">安全实验平台</a> 用起来。</li></ul><h2 id="大三-主攻期-方向成型" tabindex="-1">大三：主攻期（方向成型） <a class="header-anchor" href="#大三-主攻期-方向成型" aria-label="Permalink to &quot;大三：主攻期（方向成型）&quot;">​</a></h2><p><strong>目标</strong>：选定 1-2 个主攻方向，达到「能独立完成小项目/比赛题」的水平。</p><ul><li><strong>攻防方向</strong>：网络攻防技术（第 6 学期）、Web 安全、防火墙与入侵检测；</li><li><strong>逆向方向</strong>：软件安全（第 5 学期）、二进制安全与逆向，配合 pwn/Reverse CTF 题；</li><li><strong>数据与隐私</strong>：数据库安全、大数据安全与隐私保护、数字取证（第 5 学期）、网络舆情安全技术；</li><li><strong>前沿拓展</strong>：物联网安全、云安全、AI 安全（按兴趣选修）；</li><li><strong>合规底线</strong>：网络安全法律与伦理（第 5 学期）——务必学，安全人先学法；</li><li><strong>竞赛实战</strong>：组队参加全国大学生信息安全竞赛、主流 CTF，详见 <a href="./竞赛与成长/CTF与竞赛.html">CTF 与学科竞赛</a>。</li></ul><h2 id="大四-综合期-产出-出路" tabindex="-1">大四：综合期（产出 + 出路） <a class="header-anchor" href="#大四-综合期-产出-出路" aria-label="Permalink to &quot;大四：综合期（产出 + 出路）&quot;">​</a></h2><p><strong>目标</strong>：形成可展示的成果，明确毕业去向。</p><ul><li><strong>毕业设计</strong>：结合主攻方向选题，做出完整的安全项目（漏洞分析、安全工具、检测系统等）；</li><li><strong>实习</strong>：安全公司、政企安全部门的实习经历是就业的重要筹码；</li><li><strong>出路规划</strong>：考研/保研（<a href="./竞赛与成长/考研与深造.html">考研与深造</a>）还是就业（<a href="./竞赛与成长/就业与认证.html">就业与认证</a>），大四上学期前想清楚并做准备。</li></ul><h2 id="一张图总结" tabindex="-1">一张图总结 <a class="header-anchor" href="#一张图总结" aria-label="Permalink to &quot;一张图总结&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>大一   编程 C/Python · Linux · Git · 数学            → 会用工具</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>大二   数据结构 · 组成原理 · 操作系统 · 网络          → 懂系统</span></span>
<span class="line"><span>       信息安全数学 · 密码学 · 安全导论</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>大三   攻防 · Web安全 · 逆向 · 取证 · 隐私            → 有方向</span></span>
<span class="line"><span>       CTF + 实验平台 + 竞赛</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>大四   毕业设计 · 实习 · 考研/就业                    → 有产出</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">最重要的一句话</p><p>这份规划<strong>可以跳过、可以加速、可以重排</strong>，但有两件事没有替代品：<strong>动手实验</strong>和<strong>合法合规</strong>。所有练习都在授权环境（校内实训平台、CTF 平台、自建靶场）中进行。</p></div>`,18)])])}const u=s(r,[["render",o]]);export{d as __pageData,u as default};
